var e=JSON.parse(`"<h4>Обозначения шероховатости на чертеже (ГОСТ 2.309-73)</h4>\\n<div class=\\"hb-table\\"><table><thead><tr><th>Знак</th><th>Описание</th><th>Когда применяют</th></tr></thead><tbody>\\n<tr><td>Знак без указания способа обработки (черт. 2а)</td><td>«Галочка»: две прямые линии, сходящиеся под углом 60° (вершина угла — внизу, у линии поверхности); короткая сторона слева, длинная — справа. Высота h — высота короткой стороны, H — полная высота знака, H = (1,5…5)h. Толщина линий знака приблизительно равна половине толщины сплошной основной линии.</td><td>Применяют в обозначении шероховатости поверхности, способ обработки которой конструктором не устанавливается. При применении знака без указания параметра и способа обработки его изображают без полки.</td></tr>\\n<tr><td>Знак со снятием слоя материала (черт. 2б)</td><td>Та же «галочка» из двух линий под углом 60°, у которой верхний конец короткой (левой) стороны соединён с длинной (правой) стороной горизонтальной линией — знак замкнут сверху и образует фигуру в виде треугольника с горизонтальной верхней стороной.</td><td>Применяют в обозначении шероховатости поверхности, которая должна быть образована только удалением слоя материала.</td></tr>\\n<tr><td>Знак без снятия слоя материала (черт. 2в)</td><td>Та же «галочка» из двух линий под углом 60°, в угол которой (между линиями) вписана окружность, касающаяся обеих линий; высота h — по окружности, H — полная высота знака.</td><td>Применяют в обозначении шероховатости поверхности, которая должна быть образована без удаления слоя материала, обязательно с указанием значения параметра шероховатости. Кроме того, поверхности детали, изготавливаемой из материала определённого профиля и размера, не подлежащие по данному чертежу дополнительной обработке, отмечают этим знаком без указания параметра шероховатости (п. 1.4); состояние такой поверхности должно соответствовать требованиям стандарта или технических условий, с приведением ссылки на документ (например, указание сортамента материала в графе 3 основной надписи по ГОСТ 2.104-2006).</td></tr>\\n</tbody></table></div>\\n<p><b>Правила нанесения:</b></p>\\n<ul>\\n<li>{'пункт': '2.1', 'правило': 'Обозначения шероховатости поверхностей на изображении изделия располагают на линиях контура, выносных линиях (по возможности ближе к размерной линии) или на полках линий-выносок. Допускается при недостатке места располагать обозначение шероховатости на размерных линиях или на их продолжениях, на рамке допуска формы, а также разрывать выносную линию (черт. 7).', 'редакция': 'Измененная редакция, Изм. № 3'}</li>\\n<li>{'пункт': '2.2', 'правило': 'На линии невидимого контура допускается наносить обозначение шероховатости только в случаях, когда от этой линии нанесен размер.'}</li>\\n<li>{'пункт': '2.3', 'правило': 'Обозначения шероховатости поверхности, в которых знак имеет полку, располагают относительно основной надписи чертежа так, как показано на черт. 8 и 9 (полка знака обращена к поверхности; линии знака располагаются под углом 30° к линии поверхности).'}</li>\\n<li>{'пункт': '2.4', 'правило': 'Обозначения шероховатости поверхности, в которых знак не имеет полки, располагают относительно основной надписи чертежа так, как показано на черт. 10.', 'редакция': 'Измененная редакция, Изм. № 2, 3'}</li>\\n<li>{'пункт': '2.5', 'правило': 'При изображении изделия с разрывом обозначение шероховатости наносят только на одной части изображения, по возможности ближе к месту указания размеров (черт. 11).'}</li>\\n<li>{'пункт': '2.6', 'правило': 'При указании одинаковой шероховатости для всех поверхностей изделия обозначение шероховатости помещают в правом верхнем углу чертежа и на изображении не наносят (черт. 12). Размеры и толщина линий знака в обозначении шероховатости, вынесенном в правый верхний угол чертежа, должны быть приблизительно в 1,5 раза больше, чем в обозначениях, нанесенных на изображении. Примечание: при расположении поверхности в заштрихованной зоне обозначение наносят только на полке линии-выноски.'}</li>\\n<li>{'пункт': '2.7', 'правило': 'Обозначение шероховатости, одинаковой для части поверхностей изделия, может быть помещено в правом верхнем углу чертежа (черт. 13, 14) вместе с условным обозначением (√). Это означает, что все поверхности, на которых на изображении не нанесены обозначения шероховатости или знак √, должны иметь шероховатость, указанную перед условным обозначением (√). Размеры знака, взятого в скобки, должны быть одинаковыми с размерами знаков, нанесенных на изображении. Примечание: не допускается обозначение шероховатости или знак √ выносить в правый верхний угол чертежа при наличии в изделии поверхностей, шероховатость которых не нормируется.', 'редакция': 'Измененная редакция, Изм. № 2, 3'}</li>\\n<li>{'пункт': '2.8', 'правило': 'Обозначение шероховатости поверхностей повторяющихся элементов изделия (отверстий, пазов, зубьев и т. п.), количество которых указано на чертеже, а также обозначение шероховатости одной и той же поверхности наносят один раз, независимо от числа изображений. Обозначения шероховатости симметрично расположенных элементов симметричных изделий наносят один раз.'}</li>\\n<li>{'пункт': '2.9', 'правило': 'Если шероховатость одной и той же поверхности различна на отдельных участках, то эти участки разграничивают сплошной тонкой линией с нанесением соответствующих размеров и обозначений шероховатости (черт. 15а). Через заштрихованную зону линию границы между участками не проводят (черт. 15б).', 'редакция': 'Измененная редакция, Изм. № 2, 3'}</li>\\n<li>{'пункт': '2.10', 'правило': 'Обозначение шероховатости рабочих поверхностей зубьев зубчатых колес, эвольвентных шлицев и т. п., если на чертеже не приведен их профиль, условно наносят на линии делительной поверхности (черт. 16а, б, в), а для глобоидных червяков и сопряженных с ними колес — на линии расчетной окружности (черт. 16г).'}</li>\\n<li>{'пункт': '2.11', 'правило': 'Обозначение шероховатости поверхности профиля резьбы наносят по общим правилам при изображении профиля (черт. 17а) или условно на выносной линии для указания размера резьбы (черт. 17б, в, г, д), на размерной линии или на ее продолжении (черт. 17е).'}</li>\\n<li>{'пункт': '2.12', 'правило': 'Если шероховатость поверхностей, образующих контур, должна быть одинаковой, обозначение шероховатости наносят один раз в соответствии с черт. 18. Диаметр вспомогательного знака (окружности) — 4…5 мм. В обозначении одинаковой шероховатости поверхностей, плавно переходящих одна в другую, знак (окружность) не приводят (черт. 19).', 'редакция': 'Измененная редакция, Изм. № 1, 2, 3'}</li>\\n<li>{'пункт': '2.13', 'правило': 'Обозначение одинаковой шероховатости поверхности сложной конфигурации допускается приводить в технических требованиях чертежа со ссылкой на буквенное обозначение поверхности, например: «шероховатость поверхности A — √Ra 1,6». При этом буквенное обозначение поверхности наносят на полке линии-выноски, проведенной от утолщенной штрихпунктирной линии, которой обводят поверхность на расстоянии 0,8…1 мм от линии контура (черт. 20).', 'редакция': 'Измененная редакция, Изм. № 2, 3'}</li>\\n</ul>\\n<p><b>Примеры записи:</b> {'пункт': '1.5', 'пример': 'Ra 0,4 ; Rmax 6,3 ; Sm 0,63 ; t50 70 ; S 0,032 ; Rz 50', 'пояснение': 'Значение параметра шероховатости по ГОСТ 2789-73 указывают в обозначении шероховатости после соответствующего символа. Примечание: в примере t50 70 указана относительная опорная длина профиля tp = 70 % при уровне сечения профиля p = 50 %'}; {'пункт': '1.5а', 'пример': '√Ra 0,4 ; √Rz 50', 'пояснение': 'При указании наибольшего значения параметра шероховатости в обозначении приводят параметр шероховатости без предельных отклонений'}; {'пункт': '1.5б', 'пример': '√Ra 3,2min ; √Rz 50min', 'пояснение': 'При указании наименьшего значения параметра шероховатости после обозначения параметра следует указывать «min»'}; {'пункт': '1.6', 'пример': 'Ra 0,8 / 0,4 ; Rz 0,10 / 0,05 ; Rmax 0,80 / 0,32 ; t50 70 / 50', 'пояснение': 'При указании диапазона значений параметра пределы значений размещают в две строки; в верхней строке приводят значение, соответствующее более грубой шероховатости'}; {'пункт': '1.7', 'пример': 'Ra 1 + 20 % ; Rz 100 −10 % ; Sm 0,63 +20 % ; t50 70 ± 40 %', 'пояснение': 'При указании номинального значения параметра его приводят с предельными отклонениями по ГОСТ 2789-73'}; {'пункт': '1.8', 'пример': 'черт. 3: Ra 0,1 / 0,8 / Sm 0,063 / 0,048 / 0,25 / t50 60 ± 10 %', 'пояснение': 'При указании двух и более параметров значения записывают сверху вниз в порядке: параметр высоты неровностей профиля; параметр шага неровностей профиля; относительная опорная длина профиля'}; {'пункт': '1.11', 'пример': 'Полировать ∇ M Ra 0,025 (знак без снятия слоя, указан вид обработки)', 'пояснение': 'Вид обработки поверхности указывают в обозначении шероховатости только в случаях, когда он является единственным, применимым для получения требуемого качества поверхности (черт. 4)'}; {'пункт': '1.12', 'пример': 'Поверхности √а · √м 0,8 / Ra 0,4 ; √б ; √в ; √г', 'пояснение': 'Допускается применять упрощенное обозначение шероховатости поверхностей с разъяснением его в технических требованиях чертежа (черт. 5). В упрощенном обозначении используют знак √ и строчные буквы русского алфавита в алфавитном порядке, без повторений и, как правило, без пропусков'}; {'пункт': '2.6', 'пример': '√Ra 1,6 — в правом верхнем углу чертежа', 'пояснение': 'Одинаковая шероховатость для всех поверхностей изделия (черт. 12)'}; {'пункт': '2.7', 'пример': '√Rz 50 (√) — в правом верхнем углу чертежа (черт. 13); √(√) (черт. 14)', 'пояснение': 'Одинаковая шероховатость для части поверхностей: все поверхности без обозначения должны иметь указанную шероховатость'}; {'пункт': '2.9', 'пример': '√−0,8/Rz 0,2 и √Ra 3,2 на одном валу (черт. 15а); √Ra 0,4 и √Ra 3,2 (черт. 15б)', 'пояснение': 'Разная шероховатость одной и той же поверхности на отдельных участках'}; {'пункт': '2.12', 'пример': '√Ra 6,3 со вспомогательным знаком-окружностью (черт. 18); √Ra 12,5 и √Ra 6,3 (черт. 19)', 'пояснение': 'Одинаковая шероховатость поверхностей, образующих контур (диаметр вспомогательного знака 4…5 мм); для плавно переходящих поверхностей знак-окружность не приводят'}; {'пункт': '2.13', 'пример': '«шероховатость поверхности A — √Ra 1,6» (черт. 20)', 'пояснение': 'Одинаковая шероховатость поверхности сложной конфигурации — в технических требованиях со ссылкой на буквенное обозначение'}.</p>\\n<div class=\\"hb-note\\"><b>Внимание:</b> по данным каталога стандартов применение ГОСТ 2.309-73 в РФ прекращается с 01.10.2027 — вводится ГОСТ Р 2.309-2026 (приказ Росстандарта от 10.09.2026 № 1114-ст). В карточке на 01.06.2026 стандарт ещё числится действующим.</div>\\n</div>\\n\\n"`);export{e as default};